const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const AWS = require('aws-sdk');

const typeDefs = gql`
  type UserProfile {
    id: ID!
    name: String!
    avatar: String
    preferences: Preferences
  }

  type Preferences {
    theme: String
    notifications: Boolean
    dataExportUrl: String
  }

  type Query {
    userProfile(id: ID!): UserProfile
    exportUserData(id: ID!, format: String): String
  }

  type Mutation {
    updatePreferences(id: ID!, theme: String, notifications: Boolean): UserProfile
  }
`;

const s3 = new AWS.S3({ region: 'us-east-1' });

const EXPORT_BUCKET = process.env.EXPORT_BUCKET || 'user-data-exports-prod';

async function generateSignedExportUrl(userId, format) {
  const key = `exports/${userId}/data.${format}`;
  const params = {
    Bucket: EXPORT_BUCKET,
    Key: key,
    Expires: 3600
  };
  return s3.getSignedUrl('getObject', params);
}

const resolvers = {
  Query: {
    userProfile: async (_, { id }, context) => {
      // Fetch from database - simulated
      const user = await context.dataSources.userDB.getUser(id);
      return user; // Can return null if user not found
    },
    exportUserData: async (_, { id, format }, context) => {
      const user = await context.dataSources.userDB.getUser(id);
      // VULNERABILITY: No null check on user before accessing properties
      // If user is null, user.id throws TypeError (null pointer dereference)
      // This crashes the Node.js process if unhandled
      const exportKey = `${user.id}/${user.name}`;

      // Generate export file and upload to S3
      const exportData = JSON.stringify({
        userId: user.id,
        name: user.name,
        exportedAt: new Date().toISOString()
      });

      await s3.putObject({
        Bucket: EXPORT_BUCKET,
        Key: `exports/${exportKey}/data.${format || 'json'}`,
        Body: exportData,
        ContentType: 'application/json'
      }).promise();

      return generateSignedExportUrl(exportKey, format || 'json');
    }
  },
  Mutation: {
    updatePreferences: async (_, { id, theme, notifications }, context) => {
      const user = await context.dataSources.userDB.getUser(id);
      // Another null dereference path
      user.preferences = { ...user.preferences, theme, notifications };
      await context.dataSources.userDB.saveUser(user);
      return user;
    }
  },
  UserProfile: {
    preferences: (parent) => {
      // Nested resolver - parent could have null preferences
      return parent.preferences || { theme: 'default', notifications: true, dataExportUrl: null };
    }
  }
};

const app = express();

const server = new ApolloServer({
  typeDefs,
  resolvers,
  dataSources: () => ({
    userDB: new (require('./UserDataSource'))()
  }),
  formatError: (err) => {
    // Don't expose internal errors in production
    if (err.extensions.code === 'INTERNAL_SERVER_ERROR') {
      return new Error('An internal error occurred');
    }
    return err;
  },
  plugins: [{
    requestDidStart() {
      return {
        didEncounterErrors({ errors }) {
          errors.forEach(err => {
            if (err.originalError instanceof TypeError) {
              // Log but don't crash - however if this plugin isn't loaded
              // or error propagates before plugin catches it, process dies
              console.error('TypeError in resolver:', err.message);
            }
          });
        }
      };
    }
  }]
});

server.applyMiddleware({ app });

app.listen(4000, () => {
  console.log(`GraphQL server running at http://localhost:4000${server.graphqlPath}`);
});

module.exports = { app, server };
